/* MI-097 proof harness — old-vs-new on every design metric.
 *
 * OLD = the SYNTHETIC corpora (writing-pattern-corpus-synthetic.json),
 * engineered to the measured properties of the original 2026-10-13
 * corpora (12 template-shared drafts that fail HS-1..HS-6 at batch
 * level, and 10 post-fix drafts sharing one bridge clause and one
 * logistics string). The original corpora were built from the owner's
 * real networking drafts and were scrubbed from this repository on the
 * owner's approval, 2026-10-20.
 * NEW = waves generated by the pattern system itself (module 154's
 * composer + assembler) across six seed bases.
 *
 * The blinded read (design §8) needs human/LLM judges; this harness
 * PREPARES the unlabeled pairs file and reports it as NOT RUN rather
 * than dressing a deterministic proxy as a blinded read. Detector
 * scores are never computed or quoted (claims register).
 */
const fs = require("node:fs");
const path = require("node:path");
const W = require("../../packages/domain/154-career-writing.js");
const corpus = JSON.parse(fs.readFileSync(path.join(__dirname, "..", "..", "packages", "career-data", "fixtures", "writing-pattern-corpus-synthetic.json"), "utf8"));

const pack = (d) => [
  { id: "R", kind: "recipient", text: d.staging.recipientFact },
  { id: "S", kind: "sender", text: d.staging.senderFact },
  { id: "SL", kind: "sender", text: d.staging.senderLine },
  { id: "A", kind: "ask", text: "15 minutes" },
];
const gateOpts = (d) => ({ factPack: pack(d), recipient: { full_name: d.recipient, current_firm: d.firm, title: d.title }, senderName: d.staging.senderName });
const asBatch = (list) => list.map((d) => ({ subject: d.subject, body: d.body, firm: d.firm, recipientName: d.recipient, title: d.title, leadFactKind: "registry", factTexts: [d.staging.recipientFact] }));

function perDraft(list) {
  let pass = 0, untraced = 0, banned = 0;
  for (const d of list) {
    const c = W.slopGate(d.body, gateOpts(d));
    if (c.pass) pass++;
    untraced += c.metrics.fact_lock.value.untraced.length;
    banned += c.metrics.banned_phrases.value.hard.length + c.metrics.banned_phrases.value.markers.length;
  }
  return { pass, n: list.length, untraced, banned };
}
function batchSummary(list) {
  const v = W.batchGate(asBatch(list));
  const total = Object.keys(v.metrics).length;
  const green = Object.values(v.metrics).filter((m) => m.pass).length;
  return { pass: v.pass, green, total, failures: v.failures };
}

const FIRMS = ["Evercore", "Stripe", "Jane Street", "Lazard", "Google", "Blackstone", "McKinsey & Company", "KKR", "Bain & Company", "Goldman Sachs", "Notion", "Figma"];
const EXTRA = ["you spoke on the alumni panel last spring", "your team closed the Hartwell acquisition in March 2026", "you moved over from Morgan Stanley in 2025", "you run the analyst training each summer", "you wrote the fintech memo the partners circulated", "your group covers payments — the Stripe piece in particular", "you started as an intern and converted in 2024", "you mentor the DePaul analysts on your desk", "you presented at the Chicago fintech summit in May 2026", "you lead the sponsors coverage pod", "you hired the first data analyst for the team", "you cover consumer fintech out of the Chicago office"];
const SUBJ = [(f) => "Your move to " + f, (f) => "Question about " + f + " work", (f) => f + " — a quick question", (f) => "Chicago + " + f, (f) => "Asking about the analyst seat at " + f];
function newWave(seedBase, profile) {
  const items = FIRMS.map((f, i) => ({
    firm: f,
    fp: [
      { id: "R" + i, kind: "recipient", text: "you joined " + f + " in Chicago as an analyst in July 2026" },
      { id: "R2" + i, kind: "recipient", text: EXTRA[i] },
      { id: "S" + i, kind: "sender", text: "currently building a reporting dashboard used by " + (180 + i * 7) + " users at a campus systems job" },
      { id: "SC", kind: "sender", text: "sophomore at TEST University" },
      { id: "A", kind: "ask", text: "15 minutes" },
    ],
  }));
  const compose = (it, s) => {
    const d = W.composePatternDraft({ recipientName: "Person", senderName: "Alex Testcase (TEST)", senderLine: "a sophomore at TEST University", askTopic: "your path", factPack: it.fp, profile: profile || null, seedValue: s.seedValue, leadFactKind: s.leadFactKind, lengthTier: s.lengthTier, openingMode: s.openingMode, logisticsIndex: s.logisticsIndex, tailIndex: s.tailIndex, subject: SUBJ[FIRMS.indexOf(it.firm) % SUBJ.length](it.firm) });
    return { ...d, firm: it.firm, recipientName: "Person", title: "Analyst", factTexts: it.fp.map((f) => f.text), _fp: it.fp };
  };
  const wave = W.assembleWave(items, compose, { seedBase });
  let pass = 0, untraced = 0, banned = 0, cvPass = 0;
  for (const d of wave.drafts) {
    const c = W.slopGate(d.body, { factPack: d._fp, recipient: { full_name: "Person", current_firm: d.firm, title: "Analyst" }, senderName: "Alex Testcase (TEST)", profile: profile || null });
    if (c.pass) pass++;
    if (c.metrics.sentence_variance.pass) cvPass++;
    untraced += c.metrics.fact_lock.value.untraced.length;
    banned += c.metrics.banned_phrases.value.hard.length + c.metrics.banned_phrases.value.markers.length;
  }
  const green = Object.values(wave.verdict.metrics).filter((m) => m.pass).length;
  return { batchPass: wave.pass, batchGreen: green, batchTotal: Object.keys(wave.verdict.metrics).length, recycled: wave.recycled, perDraftPass: pass, cvPass, untraced, banned, drafts: wave.drafts };
}

const rows = [];
const waveOld = perDraft(corpus.waveSynthetic);
const waveOldBatch = batchSummary(corpus.waveSynthetic);
rows.push(["SYNTHETIC wave (engineered batch-dirty, 12 drafts)", `per-draft gate ${waveOld.pass}/${waveOld.n}`, `batch ${waveOldBatch.green}/${waveOldBatch.total} metrics green (pass=${waveOldBatch.pass})`, `untraced facts ${waveOld.untraced}`, `banned/marker hits ${waveOld.banned}`]);
const post = perDraft(corpus.approvedSynthetic);
const postBatch = batchSummary(corpus.approvedSynthetic);
rows.push(["SYNTHETIC post-fix (10 drafts)", `per-draft gate ${post.pass}/${post.n}`, `batch ${postBatch.green}/${postBatch.total} metrics green (pass=${postBatch.pass}) — shared bridge/logistics, recorded`, `untraced facts ${post.untraced}`, `banned/marker hits ${post.banned}`]);

let allNewOk = true;
for (const seedBase of [1000, 5000, 20000, 777, 31337, 42]) {
  const w = newWave(seedBase, null);
  if (!(w.batchPass && w.perDraftPass === 12 && w.untraced === 0 && w.banned === 0)) allNewOk = false;
  rows.push([`NEW generated wave (seedBase ${seedBase})`, `per-draft gate ${w.perDraftPass}/12`, `batch ${w.batchGreen}/${w.batchTotal} metrics green (pass=${w.batchPass}, recycled ${w.recycled})`, `untraced facts ${w.untraced}`, `banned/marker hits ${w.banned}`]);
}

// Profile-relative CV bar (§8): profile from the synthetic post-fix
// drafts, new wave composed + graded against it.
const profile = W.extractVoiceProfile(corpus.approvedSynthetic.map((d) => d.body));
const wp = newWave(1000, profile);
rows.push(["Profile (from approved drafts)", `CV ${profile ? profile.sentenceLength.cv : "n/a"}`, `new wave graded with profile: per-draft ${wp.perDraftPass}/12, sentence-variance metric pass ${wp.cvPass}/12`, "", ""]);

// Blinded read: prepare pairs, do not run.
const pairs = corpus.waveSynthetic.map((d, i) => ({ pair: i + 1, firm: d.firm, A: d.body, B: wp.drafts[i] ? wp.drafts[i].body : "" }));
fs.writeFileSync(path.join(__dirname, "writing-pattern-blinded-pairs-synthetic.json"), JSON.stringify({ note: "Unlabeled synthetic-vs-generated pairs for the design §8 blinded read. A/B assignment is fixed (A=synthetic fixture, B=generated) in this file — shuffle before judging. NOT RUN by this harness.", pairs }, null, 1));

console.log("WRITING-PATTERN PROOF — old vs new (module 154, MI-097)");
for (const r of rows) console.log(" | " + r.join(" | "));
console.log("§8 bars: zero banned hits on NEW: " + (rows.slice(2, 8).every((r) => /hits 0/.test(r[4])) ? "MET" : "NOT MET"));
console.log("§8 bars: zero untraced facts on NEW: " + (rows.slice(2, 8).every((r) => /facts 0/.test(r[3])) ? "MET" : "NOT MET"));
console.log("§8 bars: batch all-green on a NEW 12-wave: " + (allNewOk ? "MET (6/6 seed bases)" : "NOT MET"));
console.log("§8 bars: blinded read >=70% preference, sameness comments gone: NOT RUN — pairs prepared at scripts/career/writing-pattern-blinded-pairs-synthetic.json; no judge was available offline and no proxy is dressed as a read.");
